# Try exact solving with z3 if available
try:
    from z3 import Solver, Bool, Or, Not, And, sat, Sum, If

    solver = Solver()
    x = [Bool(f"x_{i}") for i in range(n)]

    # For each non-edge, at most one endpoint in clique
    edge_set = set()
    for u, v in edges:
        edge_set.add((min(u,v), max(u,v)))

    non_edges = []
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) not in edge_set:
                non_edges.append((i,j))

    print(f"Adding {len(non_edges)} constraints for non-edges")
    for i, j in non_edges:
        solver.add(Or(Not(x[i]), Not(x[j])))

    # At least 10 vertices in clique
    solver.add(Sum([If(x[i], 1, 0) for i in range(n)]) >= 10)

    print("Solving...")
    result = solver.check()
    print(f"Result: {result}")

    if result == sat:
        model = solver.model()
        clique = [i for i in range(n) if model.evaluate(x[i])]
        print(f"Clique found: size {len(clique)} -> {sorted(clique)}")

        # Verify
        ok = True
        for i in range(len(clique)):
            for j in range(i+1, len(clique)):
                if (min(clique[i], clique[j]), max(clique[i], clique[j])) not in edge_set:
                    ok = False
                    print(f"Bad pair: {clique[i]}, {clique[j]}")
        print(f"Verification: {ok}")
except Exception as e:
    print(f"z3 error: {e}")

    # Fallback: try pycosat / pysat
    try:
        from pysat.solvers import Solver as SATSolver
        print("Trying pysat...")
    except Exception as e2:
        print(f"pysat error: {e2}")
